package com.example.appsaudebackend.Consulta;
import com.example.appsaudebackend.Modules.Auth.Model.*;import com.example.appsaudebackend.Modules.Consulta.*;import com.example.appsaudebackend.Modules.Consulta.Dto.Request.*;import com.example.appsaudebackend.Modules.Consulta.Model.*;import com.example.appsaudebackend.Modules.Consulta.Repository.*;import com.example.appsaudebackend.Modules.Medico.Persistencia.*;import com.example.appsaudebackend.Modules.Usuarios.Persistencia.*;import com.example.appsaudebackend.Shared.Exception.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ConsultaServiceTest{@Mock ConsultaRepository consultas;@Mock UsuarioRepository usuarios;@Mock MedicoRepository medicos;@InjectMocks ConsultaService service;
@Test void pacienteAgendaParaSiMesmo(){var a=new UsuarioAuth();a.setCpf("1");a.setRole(Role.USUARIO);var p=new UsuarioModel();when(usuarios.findByUsuarioAuthCpf("1")).thenReturn(Optional.of(p));var d=new ConsultaRequestDto();d.setMedicoId(7L);d.setTipoConsulta("Geral");d.setDataHora(LocalDateTime.now().plusDays(1));var m=new MedicoModel();when(medicos.findById(7L)).thenReturn(Optional.of(m));when(consultas.existsByMedicoIdAndDataHora(7L,d.getDataHora())).thenReturn(false);service.criar(d,a);var c=ArgumentCaptor.forClass(Consulta.class);verify(consultas).save(c.capture());assertSame(p,c.getValue().getPaciente());assertEquals(StatusConsulta.AGENDADO,c.getValue().getStatus());}
@Test void horarioOcupadoRejeitaNovoAgendamento(){var a=new UsuarioAuth();a.setCpf("1");a.setRole(Role.USUARIO);when(usuarios.findByUsuarioAuthCpf("1")).thenReturn(Optional.of(new UsuarioModel()));var d=new ConsultaRequestDto();d.setMedicoId(7L);d.setDataHora(LocalDateTime.now().plusDays(1));when(medicos.findById(7L)).thenReturn(Optional.of(new MedicoModel()));when(consultas.existsByMedicoIdAndDataHora(7L,d.getDataHora())).thenReturn(true);assertThrows(RegraNegocioException.class,()->service.criar(d,a));verify(consultas,never()).save(any());}
@Test void pacienteNaoAcessaConsultaAlheia(){var u=new UsuarioAuth();u.setCpf("other");u.setRole(Role.USUARIO);var owner=new UsuarioAuth();owner.setCpf("owner");var p=new UsuarioModel();p.setUsuarioAuth(owner);var m=new MedicoModel();m.setNome("M");var c=new Consulta();c.setPaciente(p);c.setMedico(m);c.setDataHora(LocalDateTime.now());when(consultas.findById(1L)).thenReturn(Optional.of(c));assertThrows(RegraNegocioException.class,()->service.obter(1L,u));}
@Test void erroQuandoConsultaNaoExiste(){when(consultas.findById(4L)).thenReturn(Optional.empty());assertThrows(RecursoNaoEncontradoException.class,()->service.obter(4L,new UsuarioAuth()));}
}
